def transform(grid):
    # Three base patterns (5, 4, 2/8) are layers. Overlay the patterns by
    # their position: the output is the common 3x6 crop, with selected
    # cells taken from the corresponding lower layer where source is zero.
    # Demo establishes 2 from panel 3 and 4 from panel 2 supplement panel 1.
    out = []
    for r in range(3):
        row = []
        for c in range(6):
            # Most salient pattern at each location: 5-pattern wins;
            # otherwise 4-pattern, then 2-pattern; 8-pattern is a distractor.
            v = grid[r][c]
            if v == 0:
                v = grid[3+r][c]
            if v == 0:
                v = grid[6+r][c]
            row.append(v)
        out.append(row)
    return out

def transform(grid):
    # Compose the four 3x6 color layers with per-cell priorities: 5 above
    # 4, 8, and 2; use the highest-priority nonzero.
    priority = {5: 4, 4: 3, 8: 2, 2: 1}
    out=[]
    for r in range(3):
        row=[]
        for c in range(6):
            vals=[grid[k*3+r][c] for k in range(4)]
            row.append(max(vals, key=lambda v: priority.get(v,0)))
        out.append(row)
    return out
